import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Whitelist of allowed characters for a basic arithmetic expression
# Digits, whitespace, and operators + - * / ^ ( )
ALLOWED_CHAR_PATTERN = re.compile(r'^[0-9+\-*/^().\s]+$')

@app.route('/calculator', methods=['POST'])
def calculate():
    data = request.get_json(silent=True)
    if not data or 'expression' not in data:
        return jsonify({"error": "Invalid request"}), 400

    expression = data.get('expression')
    if not isinstance(expression, str):
        return jsonify({"error": "Invalid request"}), 400

    # Basic input validation: only allow digits and basic operators
    if not ALLOWED_CHAR_PATTERN.match(expression):
        return jsonify({"error": "Invalid expression"}), 400

    # Further safety check: ensure parentheses are balanced
    if expression.count('(') != expression.count(')'):
        return jsonify({"error": "Invalid expression"}), 400

    try:
        # Evaluate the expression safely using Python's eval
        # We restrict the globals and locals to prevent code injection
        # The regex above ensures only math characters are present
        result = str(eval(expression, {"__builtins__": None}, {}))
        return jsonify({"result": result}), 200
    except ZeroDivisionError:
        return jsonify({"error": "Division by zero"}), 400
    except Exception as e:
        return jsonify({"error": "Calculation error"}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
